<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\FulfillmentService;

$service=new FulfillmentService();$token=$service->extractToken((string)($_GET['t']??''));
try{$sale=$service->byToken($token);}catch(Throwable $e){http_response_code(404);exit('Comprovante de retirada não encontrado.');}
$auto=!empty($_GET['auto'])&&$sale['payment_status']==='paid';$paper=(string)($_GET['w']??'80');if(!in_array($paper,['58','80'],true))$paper='80';
function rq(mixed $v):string{$n=(float)$v;return rtrim(rtrim(number_format($n,3,',','.'),'0'),',');}
function rmoney(mixed$c):string{return'R$ '.number_format(((int)$c)/100,2,',','.');}
function payment_label(?array$p):string{if(!$p)return'Não informado';$provider=(string)($p['provider']??'');$raw=json_decode((string)($p['raw_payload']??'{}'),true);$method=is_array($raw)?(string)($raw['manual_method']??''):'';if($provider==='manual')return match($method){'cash'=>'Dinheiro','card'=>'Cartão / maquininha','pix'=>'Pix externo','other'=>'Outro',default=>'Pagamento manual'};return match($provider){'stripe'=>'Stripe','pagbank'=>'PagBank','mercadopago'=>'Mercado Pago',default=>ucfirst($provider)};}

$pdo=Database::connection();$payment=null;$unitName=null;
try{$p=$pdo->prepare('SELECT provider,raw_payload,verified_at FROM payments WHERE tenant_id=? AND order_id=? AND status="paid" ORDER BY id DESC LIMIT 1');$p->execute([(int)$sale['tenant_id'],(int)$sale['id']]);$payment=$p->fetch()?:null;}catch(Throwable){}
if(!empty($sale['unit_id']))try{$u=$pdo->prepare('SELECT name FROM business_units WHERE tenant_id=? AND id=? LIMIT 1');$u->execute([(int)$sale['tenant_id'],(int)$sale['unit_id']]);$unitName=$u->fetchColumn()?:null;}catch(Throwable){}
$qrSvg=null;
if($sale['payment_status']==='paid'&&class_exists('Endroid\\QrCode\\QrCode')){
    try{$url=rtrim((string)env('APP_URL',''),'/').'/retirada.php?t='.rawurlencode($token);$qr=new \Endroid\QrCode\QrCode(data:$url,size:300,margin:8);$writer=new \Endroid\QrCode\Writer\SvgWriter();$qrSvg=$writer->write($qr)->getString();}catch(Throwable){$qrSvg=null;}
}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Venda #<?= (int)$sale['id'] ?> — <?= Security::e($sale['tenant_name']) ?></title><style>
*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#eee;color:#111;margin:0;padding:20px}.receipt{width:<?= $paper ?>mm;max-width:100%;margin:auto;background:#fff;padding:<?= $paper==='58'?'4':'6' ?>mm;border-radius:8px}.center{text-align:center}.brand{font-size:19px;font-weight:800}.muted{color:#555;font-size:11px}.line{border-top:1px dashed #777;margin:10px 0}.meta{font-size:11px;line-height:1.5}.meta div{display:flex;justify-content:space-between;gap:10px}.item{padding:8px 0;border-bottom:1px dashed #aaa}.item:last-child{border-bottom:0}.item-head{display:flex;justify-content:space-between;gap:8px;font-size:12px}.item-sub{display:flex;justify-content:space-between;gap:8px;margin-top:3px;font-size:10px;color:#555}.numbers{display:grid;grid-template-columns:repeat(3,1fr);gap:4px;margin-top:6px;text-align:center}.numbers div{border:1px solid #bbb;padding:4px 2px;border-radius:4px}.numbers strong{display:block;font-size:16px}.totals{font-size:11px}.totals div{display:flex;justify-content:space-between;padding:2px 0}.totals .grand{font-size:16px;font-weight:800;border-top:1px solid #111;margin-top:5px;padding-top:6px}.qr svg{width:<?= $paper==='58'?'39':'45' ?>mm;height:auto;background:white}.status{padding:7px;border:2px solid #111;border-radius:5px;font-weight:700;font-size:11px}.code{font-family:monospace;font-size:9px;word-break:break-all}.actions{text-align:center;margin:15px}.actions button,.actions a{display:inline-block;padding:10px 14px;font-weight:700;margin:3px}.paper-switch{font-size:12px}@media print{body{background:#fff;padding:0}.receipt{width:<?= $paper ?>mm;border-radius:0;padding:<?= $paper==='58'?'3':'4' ?>mm}.actions{display:none}@page{size:<?= $paper ?>mm auto;margin:0}}
</style></head><body><div class="actions"><button onclick="window.print()">Imprimir</button><a class="paper-switch" href="<?= Security::e(app_url('/retirada.php?t='.rawurlencode($token).'&w='.($paper==='80'?'58':'80'))) ?>">Usar <?= $paper==='80'?'58':'80' ?> mm</a></div><main class="receipt"><div class="center"><div class="brand"><?= Security::e($sale['tenant_name']) ?></div><?php if($unitName):?><div class="muted"><?= Security::e((string)$unitName) ?></div><?php endif;?><div class="muted">EventMenu Premium</div><h2 style="margin:8px 0">VENDA #<?= (int)$sale['id'] ?></h2><div class="status"><?= Security::e(strtoupper((string)$sale['payment_status'])) ?> · RETIRADA <?= Security::e(strtoupper((string)$sale['fulfillment_status'])) ?></div></div><div class="line"></div><div class="meta"><div><span>Cliente</span><strong><?= Security::e($sale['customer_name']??'Consumidor') ?></strong></div><div><span>Canal</span><strong><?= Security::e($sale['channel']==='counter'?'Balcão':'Retirada') ?></strong></div><div><span>Pagamento</span><strong><?= Security::e(payment_label($payment)) ?></strong></div><div><span>Data</span><strong><?= Security::e((string)$sale['created_at']) ?></strong></div></div><div class="line"></div><?php foreach($sale['items'] as$item):?><div class="item"><div class="item-head"><strong><?= Security::e($item['name_snapshot']) ?></strong><strong><?= rmoney($item['total_cents']) ?></strong></div><div class="item-sub"><span><?= Security::e(rq($item['quantity'])) ?> × <?= rmoney($item['unit_price_cents']) ?></span><span>Item #<?= (int)$item['id'] ?></span></div><div class="numbers"><div><span class="muted">Comprou</span><strong><?= Security::e(rq($item['quantity'])) ?></strong></div><div><span class="muted">Retirou</span><strong><?= Security::e(rq($item['fulfilled_quantity'])) ?></strong></div><div><span class="muted">Saldo</span><strong><?= Security::e(rq($item['remaining_quantity'])) ?></strong></div></div></div><?php endforeach;?><div class="line"></div><div class="totals"><div><span>Subtotal</span><strong><?= rmoney($sale['subtotal_cents']) ?></strong></div><?php if((int)$sale['discount_cents']>0):?><div><span>Desconto</span><strong>- <?= rmoney($sale['discount_cents']) ?></strong></div><?php endif;?><div class="grand"><span>TOTAL</span><strong><?= rmoney($sale['total_cents']) ?></strong></div></div><?php if(!empty($sale['notes'])):?><div class="line"></div><div class="meta"><strong>Observação</strong><br><?= nl2br(Security::e((string)$sale['notes'])) ?></div><?php endif;?><div class="line"></div><div class="center"><?php if($sale['payment_status']==='paid'):?><?php if($qrSvg):?><div class="qr"><?= $qrSvg ?></div><?php endif;?><p><strong>APRESENTE ESTE QR PARA RETIRAR</strong></p><p class="muted">Cada entrega reduz apenas o saldo de retirada. O estoque já foi comprometido na venda e não é baixado novamente.</p><p class="code"><?= Security::e($token) ?></p><?php else:?><p class="status">AGUARDANDO PAGAMENTO</p><p class="muted">Este comprovante não libera retirada enquanto a venda não estiver totalmente paga.</p><?php endif;?></div><div class="line"></div><p class="muted center"><?php if((float)$sale['remaining_items']<=0.000001):?><strong>RETIRADA CONCLUÍDA</strong><br>Todos os itens desta venda já foram entregues.<?php else:?><strong>SALDO PENDENTE: <?= Security::e(rq($sale['remaining_items'])) ?></strong><br>O mesmo QR pode ser usado nas próximas retiradas até zerar o saldo.<?php endif;?></p></main><?php if($auto):?><script>addEventListener('load',()=>setTimeout(()=>window.print(),250));</script><?php endif;?></body></html>
